import java.util.Scanner; public class TestClass { public static void main(String[] args) { Scanner sc = new Scanner(System.in); if (!sc.hasNextLong()) return; long L = sc.nextLong(); long R = sc.nextLong(); long xorR = getXor(R); long xorLMinus1 = getXor(L - 1); long result = xorR ^ xorLMinus1; if ((result & 1) == 0) { System.out.println("even"); } else { System.out.println("odd"); } } private static long getXor(long n) { if (n < 0) return 0; long rem = n % 4; if (rem == 0) return n; if (rem == 1) return 1; if (rem == 2) return n + 1; return 0; } }